import {esc,fmt,signed,seasonFor,csv,selectProduct,color} from './lib.js';

const icons={explorer:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2V5zm6-2v16m6-14v16',trends:'M3 17l6-5 4 3 8-10M15 5h6v6',lab:'M9 3h6m-5 0v6L4 19a1 1 0 001 2h14a1 1 0 001-2L14 9V3M8 14h8',products:'M4 7h16v14H4zM3 3h18v4H3zm6 9h6',methods:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',download:'M12 3v12m-5-5l5 5 5-5M4 16v5h16v-5',arrow:'M5 12h14m-5-5l5 5-5 5',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1114 0zM12 7v5',play:'M8 5l11 7-11 7V5',pause:'M8 5v14M16 5v14',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',check:'M4 12l5 5L20 6'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.arrow}"/></svg>`;
const labels={explorer:'Species explorer',trends:'Population trends',lab:'Experiment lab',products:'Data products',methods:'Methods & lineage'};
const seasons={all:'Full annual cycle',nonbreeding:'Nonbreeding',prebreeding_migration:'Pre-breeding migration',breeding:'Breeding',postbreeding_migration:'Post-breeding migration'};
const state={view:labels[location.hash.slice(1)]?location.hash.slice(1):'explorer',week:25,region:'all',layer:'abundance',season:'all',play:false,selected:null,product:'weekly',productRegion:'all',productSeason:'all',format:'csv'};
let data,base,statusGeo,trendGeo,regionsGeo,timer=null;
const $=s=>document.querySelector(s);
const regionName=id=>id==='all'?'Michigan · all supported cells':data.regions.find(x=>x.id===id)?.name||id;
const regionShort=id=>id==='all'?'Michigan':data.regions.find(x=>x.id===id)?.name||id;
const dateLabel=d=>new Date(`${d}T12:00:00Z`).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const series=()=>data.weekly_summary.filter(x=>x.region===state.region);
const current=()=>series().find(x=>x.week===state.week);
const trend=()=>data.regional_trends.find(x=>x.region===state.region);
const regionOptions=(selected,all=true)=>`${all?`<option value="all" ${selected==='all'?'selected':''}>All Michigan</option>`:''}${data.regions.map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${r.name}</option>`).join('')}`;
const seasonOptions=selected=>Object.entries(seasons).map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('');

async function boot(){
 try {
  [data,base,statusGeo,trendGeo,regionsGeo]=await Promise.all(['analysis.json','basemap.geojson','status.geojson','trends.geojson','regions.geojson'].map(async f=>{
   const r=await fetch(`./data/${f}`);if(!r.ok)throw new Error(`Could not load ${f}`);return r.json();
  }));
  render();
 } catch(e) {
  $('#app').innerHTML=`<main class="load-error"><p class="eyebrow">© BirdScope</p><h1>The data couldn’t load.</h1><p>${esc(e.message)}. Serve this folder over HTTP, or check your connection.</p><button id="retry" class="button primary">Try again</button></main>`;
  $('#retry').onclick=boot;
 }
}

function render(){
 $('#app').innerHTML=`<a class="skip" href="#main">Skip to analysis</a>
 <header class="site-header"><div class="masthead"><a href="#explorer" class="brand" aria-label="BirdScope home">© BirdScope</a><div class="masthead-context">Avian data & conservation</div><a class="text-link masthead-link" href="#methods">About the data ${icon('arrow',16)}</a></div>
 <nav class="main-nav" aria-label="Main navigation">${Object.entries(labels).map(([key,label])=>`<a href="#${key}" class="nav-link ${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav></header>
 <div class="workspace"><div class="topbar"><div class="breadcrumbs">eBird analysis <span>/</span> ${labels[state.view]}</div><span class="study-location">${state.view==='lab'?'Singapore · 2012':'Michigan, USA · 27 km'}</span></div>
 <main id="main" tabindex="-1">${({explorer:explorerView,trends:trendsView,lab:labView,products:productsView,methods:methodsView}[state.view])()}</main>
 <footer class="footer"><span>© ${new Date().getFullYear()} BirdScope</span><span>Data: eBird Status and Trends · Cornell Lab of Ornithology</span><a href="#methods">Sources & methods ${icon('external',14)}</a></footer></div><div class="toast" id="toast" role="status" hidden></div>`;
 bind();
}

function heading(kicker,title,description,action=true){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${description}</p></div>${action?`<a class="button" href="./downloads/conservation-brief.html" target="_blank" rel="noopener">${icon('download',17)} Conservation brief</a>`:''}</div>`;}
function metric(label,value,detail,extra=''){return `<div class="metric ${extra}"><span class="metric-label">${label}</span><strong>${value}</strong><span class="metric-detail">${detail}</span></div>`;}
function filters(){return `<div class="filterbar"><div class="species-filter"><span class="filter-label">SPECIES</span><strong>Yellow-bellied Sapsucker</strong><span class="latin">Sphyrapicus varius</span></div><label><span class="filter-label">STUDY REGION</span><select id="region">${regionOptions(state.region)}</select></label><label><span class="filter-label">SEASON</span><select id="season">${seasonOptions(state.season)}</select></label><div class="version"><span class="filter-label">STATUS RELEASE</span><strong>2023 <span class="muted">/ 27 km</span></strong></div></div>`;}
function explorerView(){
 const now=current(),t=trend(),peak=series().reduce((a,b)=>(a.abundance??-1)>(b.abundance??-1)?a:b);
 return `${heading('01 / SPECIES EXPLORER','Seasonal abundance','Explore modeled abundance across Michigan, one week at a time.')}${filters()}
 <div class="metrics">${metric('Relative abundance',fmt(now.abundance,3),`${dateLabel(now.date)} · area-weighted mean`,'accent')}${metric('Peak week',dateLabel(peak.date),`${fmt(peak.abundance,3)} relative abundance units`)}${metric('Breeding population trend',`${signed(t.annual_percent)}<small>% / yr</small>`,`2012–2022 · ${t.direction}`)}${metric('Spatial support',fmt(now.cells,0),`${fmt(now.supported_area_km2,0)} km² of modeled support`)}</div>
 <div class="explore-grid"><section class="panel map-panel"><div class="panel-heading"><div><p class="eyebrow">SPATIAL DISTRIBUTION</p><h2>${state.layer==='elevation'?'Environmental covariate':state.layer==='occurrence'?'Encounter probability':'Relative abundance'}</h2></div><div class="segmented" role="group" aria-label="Map layer">${[['abundance','Abundance'],['occurrence','Occurrence'],['elevation','Elevation']].map(([k,n])=>`<button data-layer="${k}" class="${state.layer===k?'selected':''}" aria-pressed="${state.layer===k}">${n}</button>`).join('')}</div></div>${mapMarkup(false)}<div class="timeline"><button class="play-button" id="play" aria-label="${state.play?'Pause':'Play'} annual cycle">${icon(state.play?'pause':'play',18)}</button><div class="timeline-control"><label for="week"><span>WEEK ${String(state.week).padStart(2,'0')}</span><strong>${dateLabel(now.date)}, 2023</strong><span class="season-name">${seasons[seasonFor(now.date,data.metadata.season_dates)]}</span></label><input type="range" id="week" min="1" max="52" value="${state.week}" aria-valuetext="${dateLabel(now.date)}, week ${state.week}"><div class="range-labels"><span>JAN</span><span>APR</span><span>JUL</span><span>OCT</span><span>DEC</span></div></div></div></section>
 <aside class="insight-stack"><section class="panel annual-panel"><div class="panel-heading"><div><p class="eyebrow">PHENOLOGY</p><h2>Annual cycle</h2></div><span class="pill">52 weeks</span></div>${cycleChart()}<p class="chart-note">Area-weighted relative abundance · ${regionShort(state.region)}. Click a week to explore.</p><div class="small-divider"></div><div class="takeaway"><span class="number-label">01</span><div><strong>Seasonality, measured.</strong><p>The highest modeled mean in this region is in the week of ${dateLabel(peak.date)}. A seasonal peak is not a population trend.</p></div></div></section>
 <section class="panel detail-panel" id="cell-detail">${cellDetails()}</section><div class="source-note">${icon('methods',17)}<p>Source: Cornell’s <a href="https://ebird.github.io/ebirdst/" target="_blank" rel="noopener">ebirdst teaching sample</a>. Expected counts under standardized observation conditions; not a bird census.</p></div></aside></div>
 <section class="panel region-panel"><div class="panel-heading"><div><p class="eyebrow">REGIONAL COMPARISON</p><h2>Regional comparison</h2></div><span class="muted">Custom latitude bands · ${dateLabel(now.date)}</span></div>${regionTable()}<p class="panel-note">Bands split Michigan at 44°N and 45.5°N. Cell contributions are weighted by intersection area. The bands are analytical regions, not ecological boundaries.</p></section>`;
}

function project(c){const k=87.8;return [150+(c[0]+91.5)*Math.cos(Math.PI/4)*k,(48.7-c[1])*k];}
function pathGeometry(g){
 const ring=r=>r.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(2)).join(',')}`).join('')+'Z';
 if(g.type==='Polygon')return g.coordinates.map(ring).join('');
 if(g.type==='MultiPolygon')return g.coordinates.map(p=>p.map(ring).join('')).join('');
 if(g.type==='GeometryCollection')return g.geometries.map(pathGeometry).join('');
 return '';
}
function mapMarkup(isTrend){
 const geo=isTrend?trendGeo:statusGeo;
 const vals=geo.features.map(f=>isTrend?f.properties.abd_ppy:state.layer==='elevation'?f.properties.elevation_m:f.properties[state.layer][state.week-1]);
 const globalMax=isTrend?6:state.layer==='occurrence'?1:state.layer==='elevation'?600:Math.max(...statusGeo.features.flatMap(f=>f.properties.abundance).filter(v=>v!=null));
 const features=geo.features.filter(f=>state.region==='all'||f.properties.regions.includes(state.region));
 const subset=new Set(features.map(f=>isTrend?f.properties.srd_id:f.properties.cell_id));
 const title=isTrend?'Breeding trend (% per year)':state.layer==='elevation'?'Mean elevation (m)':state.layer==='occurrence'?'Encounter probability':'Relative abundance';
 const selected=state.selected;
 const paths=geo.features.map((f,i)=>{const p=f.properties,id=isTrend?p.srd_id:p.cell_id,active=subset.has(id);return `<path d="${pathGeometry(f.geometry)}" fill="${color(vals[i],globalMax,isTrend)}" class="data-cell ${String(selected)===String(id)?'cell-selected':''}" opacity="${active?1:.12}" data-cell="${id}" data-trend="${isTrend}" ${active?'tabindex="0" role="button"':''} aria-label="${esc(`Cell ${id}: ${fmt(vals[i],3)} ${isTrend?'percent per year':state.layer}. Select for details.`)}"><title>Cell ${id}: ${fmt(vals[i],3)}${isTrend?'% / year':''}</title></path>`}).join('');
 const grid=[42,44,46,48].map(lat=>{const y=project([-91.5,lat])[1];return `<line x1="0" x2="960" y1="${y}" y2="${y}"/><text x="15" y="${y-7}">${lat}°N</text>`}).join('');
 const lakeLabel=(text,coords,angle=0)=>{const [x,y]=project(coords);return `<text class="lake-label" x="${x}" y="${y}" transform="rotate(${angle},${x},${y})">${text}</text>`;};
 const mask=state.region==='all'?'':regionsGeo.features.filter(f=>f.properties.region===state.region).map(f=>`<path d="${pathGeometry(f.geometry)}" fill="none" stroke="#152d2f" stroke-width="2" stroke-dasharray="5 4" pointer-events="none"/>`).join('');
 return `<div class="map-wrap"><div class="map-meta"><span>${icon('pin',14)} ${regionShort(state.region)}</span><span>${isTrend?'2012–2022 · breeding':'27 km · native grid'}</span></div><svg class="geographic-map" viewBox="0 0 960 650" role="group" aria-label="${title} map of Michigan. Select a cell for details."><rect width="960" height="650" fill="#edf3f8"/><g class="map-graticule">${grid}</g><g class="map-land">${base.features.map(f=>`<path d="${pathGeometry(f.geometry)}"/><title>${esc(f.properties.name)}</title>`).join('')}</g><g>${paths}</g>${mask}${lakeLabel('LAKE SUPERIOR',[-87.6,47.5])}${lakeLabel('LAKE MICHIGAN',[-87.0,44.2],-73)}${lakeLabel('LAKE HURON',[-82.6,44.7],-38)}<text class="state-label" x="${project([-89.6,44.5])[0]}" y="${project([-89.6,44.5])[1]}">WISCONSIN</text><text class="state-label" x="${project([-82.5,47.0])[0]}" y="${project([-82.5,47.0])[1]}">ONTARIO</text><g transform="translate(908,76)"><path d="M0 26V0m-7 10L0 0l7 10" fill="none" stroke="#365057" stroke-width="1.4"/><text x="0" y="-10" text-anchor="middle" fill="#365057" font-size="12">N</text></g></svg><div class="map-legend"><strong>${title}</strong><div class="gradient ${isTrend?'diverging':''}"></div><div class="legend-ticks"><span>${isTrend?'≤ −6':0}</span><span>${isTrend?'0':fmt(globalMax/4, state.layer==='elevation'?0:2)}</span><span>${isTrend?'≥ +6':fmt(globalMax, state.layer==='elevation'?0:2)}</span></div><span class="legend-note">${isTrend?'Linear scale · source ensemble estimates':'Square-root color scale · fixed across weeks'}</span></div><span class="map-credit">Natural Earth / Cornell Lab</span></div>`;
}

function cycleChart(){
 const rows=series(),W=380,H=205,p={l:42,r:12,t:22,b:30},max=Math.max(...rows.map(x=>x.abundance??0))*1.12;
 const x=i=>p.l+i*(W-p.l-p.r)/51,y=v=>H-p.b-(v/max)*(H-p.t-p.b);
 const lines=[0,.5,1].map(v=>`<line class="chart-grid" x1="${p.l}" x2="${W-p.r}" y1="${y(v*max)}" y2="${y(v*max)}"/><text class="chart-label" x="${p.l-9}" y="${y(v*max)+4}" text-anchor="end">${fmt(v*max,1)}</text>`).join('');
 const points=rows.map((r,i)=>`${x(i)},${y(r.abundance??0)}`).join(' ');
 const now=current(),cx=x(state.week-1),cy=y(now.abundance??0);
 return `<svg class="cycle-chart" viewBox="0 0 ${W} ${H}" role="group" aria-label="52 weekly area-weighted abundance estimates">${lines}<polygon points="${p.l},${H-p.b} ${points} ${W-p.r},${H-p.b}" fill="#e4f1d9"/><polyline points="${points}" fill="none" stroke="#296239" stroke-width="2.5"/><line x1="${cx}" x2="${cx}" y1="${p.t}" y2="${H-p.b}" stroke="#72936a" stroke-dasharray="3 4"/><circle cx="${cx}" cy="${cy}" r="5" fill="#1c3022" stroke="white" stroke-width="2"/>${[0,13,26,39,51].map((w,i)=>`<text class="chart-label" x="${x(w)}" y="${H-7}" text-anchor="middle">${['JAN','APR','JUL','OCT','DEC'][i]}</text>`).join('')}${rows.map((r,i)=>`<rect x="${x(i)-3}" y="15" width="${(W-p.l-p.r)/52+1}" height="${H-40}" fill="transparent" data-week="${i+1}" tabindex="0" role="button" aria-label="${dateLabel(r.date)}: ${fmt(r.abundance,3)}"><title>${dateLabel(r.date)} · ${fmt(r.abundance,3)}</title></rect>`).join('')}</svg>`;
}
function cellDetails(){
 const isTrend=state.view==='trends';
 const f=(isTrend?trendGeo:statusGeo).features.find(f=>String(isTrend?f.properties.srd_id:f.properties.cell_id)===String(state.selected));
 if(!f)return `<p class="eyebrow">CELL INSPECTOR</p><h3>Inspect a cell</h3><p>Select a map cell to inspect its estimate, uncertainty, and spatial context.</p><span class="inspector-hint">${icon('explorer',18)} Select by mouse, or Tab + Enter</span>`;
 const p=f.properties;
 return `<p class="eyebrow">CELL ${isTrend?p.srd_id:p.cell_id}</p><h3>${isTrend?'Breeding trend':'Weekly estimate'}</h3><div class="inspector-value">${isTrend?signed(p.abd_ppy)+'<small>% / yr</small>':fmt(p.abundance[state.week-1],3)}</div><dl class="detail-list"><div><dt>${isTrend?'80% source interval':'Pointwise 10–90% interval'}</dt><dd>${isTrend?signed(p.abd_ppy_lower)+' to '+signed(p.abd_ppy_upper):fmt(p.lower[state.week-1],3)+' – '+fmt(p.upper[state.week-1],3)}</dd></div>${isTrend?`<div><dt>Cumulative change</dt><dd>${signed(p.abd_trend)}%</dd></div>`:`<div><dt>Occurrence probability</dt><dd>${fmt(p.occurrence[state.week-1],3)}</dd></div><div><dt>Mean elevation</dt><dd>${fmt(p.elevation_m,0)} m</dd></div><div><dt>Clipped cell area</dt><dd>${fmt(p.area_km2,1)} km²</dd></div>`}</dl><p class="small">${isTrend?'Source cell intervals are distinct from regional ensemble intervals.':'A cell-level interval cannot be averaged to obtain a regional confidence interval.'}</p>`;
}
function regionTable(){
 const list=data.regions.map(r=>({r,s:data.weekly_summary.find(s=>s.region===r.id&&s.week===state.week),t:data.regional_trends.find(t=>t.region===r.id)}));
 const max=Math.max(...list.map(x=>x.s.abundance??0),.001);
 return `<div class="table-wrap"><table><thead><tr><th>Analytical region</th><th>Relative abundance</th><th>Supported area</th><th>Breeding trend / yr</th><th>80% interval</th></tr></thead><tbody>${list.map(({r,s,t})=>`<tr><td><button class="table-region" data-region="${r.id}">${r.name} ${icon('arrow',15)}</button></td><td><div class="bar-value"><span>${fmt(s.abundance,3)}</span><div class="inline-bar"><i style="width:${(s.abundance??0)/max*100}%"></i></div></div></td><td>${fmt(s.supported_area_km2,0)} km²</td><td>${signed(t.annual_percent)}% <span class="direction ${t.direction}">${t.direction}</span></td><td>${signed(t.lower)} to ${signed(t.upper)}%</td></tr>`).join('')}</tbody></table></div>`;
}

function forestChart(){
 const rows=data.regional_trends,min=Math.min(...rows.map(t=>t.lower),-2),max=Math.max(...rows.map(t=>t.upper),1.5),x=v=>130+(v-min)/(max-min)*310;
 return `<svg viewBox="0 0 470 270" class="forest-chart" role="img" aria-label="Regional annual trend estimates with 80 percent ensemble intervals"><line x1="${x(0)}" x2="${x(0)}" y1="20" y2="225" stroke="#899b97" stroke-dasharray="4 4"/>${rows.map((r,i)=>{const y=48+i*53;return `<text x="0" y="${y+4}" class="chart-label">${regionShort(r.region)}</text><line x1="${x(r.lower)}" x2="${x(r.upper)}" y1="${y}" y2="${y}" stroke="${r.direction==='declining'?'#b24836':'#23796b'}" stroke-width="4"/><circle cx="${x(r.annual_percent)}" cy="${y}" r="6" fill="${r.direction==='declining'?'#b24836':'#23796b'}" stroke="white" stroke-width="2"/><text x="${x(r.annual_percent)}" y="${y-13}" class="chart-label" text-anchor="middle">${signed(r.annual_percent)}%</text>`}).join('')}${[-2,-1,0,1].map(v=>`<text x="${x(v)}" y="255" class="chart-label" text-anchor="middle">${v>0?'+':''}${v}%</text>`).join('')}</svg>`;
}
function trendsView(){
 const t=trend();
 return `${heading('02 / POPULATION TRENDS','Population trends','Breeding-season trends from a separate 2012–2022 data product.')}
 <div class="filterbar compact"><label><span class="filter-label">STUDY REGION</span><select id="region">${regionOptions(state.region)}</select></label><div><span class="filter-label">SPECIES</span><strong>Yellow-bellied Sapsucker</strong></div><div><span class="filter-label">ENSEMBLE</span><strong>100 source replicates</strong></div><div><span class="filter-label">SEASON WINDOW</span><strong>May 24 – August 16</strong></div></div>
 <div class="metrics">${metric('Regional annual trend',`${signed(t.annual_percent)}<small>% / yr</small>`,'Abundance × area weighted','accent')}${metric('80% ensemble interval',`${signed(t.lower)} <small>to</small> ${signed(t.upper)}`,'Percent change per year')}${metric('Interval-based direction',t.direction[0].toUpperCase()+t.direction.slice(1),t.direction==='uncertain'?'The interval includes zero':'The interval excludes zero')}${metric('Trend cells',fmt(t.cells,0),'Own grid · distinct from Status')}</div>
 <div class="explore-grid"><section class="panel map-panel"><div class="panel-heading"><div><p class="eyebrow">BREEDING TRENDS / 2012–2022</p><h2>A spatial view of change</h2></div><span class="pill">% per year</span></div>${mapMarkup(true)}<p class="panel-note">All source estimates are shown, including cells whose intervals cross zero. Select a cell to inspect uncertainty.</p></section><aside class="insight-stack"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">REGIONAL UNCERTAINTY</p><h2>Regional trend intervals</h2></div></div>${forestChart()}<p class="panel-note">Median and 10th–90th percentiles across regional ensemble estimates. These are not averaged cell bounds.</p></section><section class="panel detail-panel" id="cell-detail">${cellDetails()}</section></aside></div>
 <section class="science-callout"><span class="number-label">METHOD</span><div><h3>Aggregate the ensemble, then quantify uncertainty.</h3><p>For each source replicate, weight every cell’s annual trend by its relative abundance and regional intersection area. Calculate the regional median and interval across those 100 replicate summaries. Status and Trends have different grids and releases; they are processed independently.</p></div><a href="#methods" class="text-link">Read the method ${icon('arrow',17)}</a></section>`;
}

function calibrationChart(){
 const models=data.experiment.models.filter(x=>x.id!=='prevalence'),colors=['#296239','#bc6741'];
 return `<svg viewBox="0 0 460 255" role="img" aria-label="Out-of-fold calibration: predicted versus observed detection frequency"><line x1="50" y1="205" x2="420" y2="25" stroke="#b9c4c1" stroke-dasharray="5 5"/>${[0,.5,1].map(v=>`<line x1="50" x2="420" y1="${205-v*180}" y2="${205-v*180}" class="chart-grid"/><text x="38" y="${209-v*180}" text-anchor="end" class="chart-label">${v}</text><text x="${50+v*370}" y="226" text-anchor="middle" class="chart-label">${v}</text>`).join('')}${models.map((m,i)=>`<polyline points="${m.calibration.map(p=>`${50+p.predicted*370},${205-p.observed*180}`).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2"/>${m.calibration.map(p=>`<circle cx="${50+p.predicted*370}" cy="${205-p.observed*180}" r="${Math.max(3,Math.sqrt(p.n))}" fill="${colors[i]}" opacity=".8"><title>${m.name}: ${p.n} visits; predicted ${fmt(p.predicted)}, observed ${fmt(p.observed)}</title></circle>`).join('')}`).join('')}<text x="235" y="251" text-anchor="middle" class="chart-label">Predicted detection probability</text><text x="13" y="115" transform="rotate(-90,13,115)" text-anchor="middle" class="chart-label">Observed frequency</text></svg>`;
}
function labView(){
 const c=data.checklists,e=data.experiment;
 if(e.status!=='complete')return `${heading('03 / EXPERIMENT LAB','Insufficient data.','More eligible visits and spatial blocks are needed for evaluation.',false)}<p>${esc(e.reason)}</p>`;
 const delta=e.comparison,verdict=delta.upper<0?'Evidence of improvement':delta.lower>0?'Evidence of worse prediction':'No clear improvement';
 return `${heading('03 / EXPERIMENT LAB','Model evaluation','A separate checklist experiment · Collared Kingfisher · Singapore, 2012.',false)}<div class="notice"><span class="pill">SEPARATE DATASET</span><p>This analysis uses the official auk checklist sample for Singapore. Its detection models are separate from the Michigan Status and Trends products.</p></div>
 <div class="metrics">${metric('Eligible independent visits',fmt(c.eligible_visits,0),`${c.raw_sampling_events} original sampling events`,'accent')}${metric('Observed detections',fmt(c.detections,0),`${fmt(c.prevalence*100,1)}% detection frequency`)}${metric('Non-detections',fmt(c.nondetections,0),'Complete checklists only')}${metric('Spatial groups',fmt(c.spatial_blocks,0),`${e.folds.length} folds · repeated localities kept together`)}</div>
 <section class="panel"><div class="panel-heading"><div><p class="eyebrow">PRE-SPECIFIED EXPERIMENT</p><h2>Does spatial and seasonal context help?</h2></div><span class="pill">Held-out spatial groups</span></div><div class="table-wrap"><table class="model-table"><thead><tr><th>Candidate</th><th>Brier score ↓</th><th>ROC AUC ↑</th><th>Average precision ↑</th><th>Log loss ↓</th></tr></thead><tbody>${e.models.map((m,i)=>`<tr><td><span class="model-index">0${i+1}</span><strong>${m.name}</strong><span class="table-sub">${m.id==='prevalence'?'Training-fold prevalence only':`${m.features.length} features · regularized logistic regression`}</span></td><td>${fmt(m.brier,4)}</td><td>${fmt(m.roc_auc,3)}</td><td>${fmt(m.average_precision,3)}</td><td>${fmt(m.log_loss,3)}</td></tr>`).join('')}</tbody></table></div><div class="experiment-result"><span class="result-icon">≈</span><div><strong>${verdict}</strong><p>Adding space and season changes Brier score by ${signed(delta.delta_brier,4)}. Paired block-bootstrap 95% interval: ${signed(delta.lower,4)} to ${signed(delta.upper,4)}. Lower is better; this is a small teaching sample.</p></div></div></section>
 <div class="two-col"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">DATA QUALITY</p><h2>Checklist eligibility</h2></div></div><div class="funnel">${c.stages.map(s=>`<div class="funnel-row"><div><span>${s.stage}</span><strong>${s.remaining}</strong></div><div class="funnel-track"><i style="width:${s.remaining/c.raw_sampling_events*100}%"></i></div><small>${s.removed?`${s.removed} excluded at this step`:'No exclusions at this step'}</small></div>`).join('')}</div><p class="panel-note">Presence-only “X” records remain detections with unknown counts (${c.presence_only_counts} eligible visits). Non-detection does not prove absence.</p></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">CALIBRATION</p><h2>Do probabilities match observations?</h2></div></div><div class="calibration">${calibrationChart()}</div><div class="chart-key"><span><i style="background:#296239"></i>Effort only</span><span><i style="background:#bc6741"></i>Effort + space + season</span></div><p class="panel-note">Circle area represents bin size. Sparse bins are unstable; the diagonal represents perfect calibration. Predictions are held out by spatial group.</p><div class="small-divider"></div><div class="panel-inner"><h3>Design choices that protect the result</h3><ul class="method-list"><li>Same folds and visits for every candidate.</li><li>Scaling fits on training data only.</li><li>Shared visits deduplicated; repeated localities stay in one fold.</li><li>No post-hoc tuning to make the candidate win.</li><li>${delta.replicates} paired block-bootstrap resamples; predictions held fixed.</li></ul><p class="small">There is no buffer between neighboring blocks and observers can cross folds. Larger spatial blocks, temporal holdouts and independent data remain necessary before operational use.</p></div></section></div>`;
}

function productsView(){
 const rows=selectProduct(data,state.productRegion,state.product,state.productSeason);
 const headers=rows.length?Object.keys(rows[0]):[];
 return `${heading('04 / DATA PRODUCTS','Data products','Create a regional extract, inspect it, and take the provenance with you.',false)}<div class="product-grid"><section class="panel product-builder"><p class="eyebrow">CUSTOM DATA REQUEST</p><h2>Configure an extract</h2><label>Product<select id="product"><option value="weekly" ${state.product==='weekly'?'selected':''}>Weekly status summaries</option><option value="trends" ${state.product==='trends'?'selected':''}>Regional breeding trends</option></select></label><label>Region<select id="product-region"><option value="every" ${state.productRegion==='every'?'selected':''}>Michigan + all three bands</option>${regionOptions(state.productRegion)}</select></label><label>Season<select id="product-season" ${state.product==='trends'?'disabled':''}>${seasonOptions(state.productSeason)}</select></label><label>File format<select id="format"><option value="csv" ${state.format==='csv'?'selected':''}>CSV · spreadsheet ready</option><option value="json" ${state.format==='json'?'selected':''}>JSON · machine readable</option></select></label><div class="extract-summary"><strong>${rows.length} rows</strong><span>${headers.length} fields · derived regional summaries</span></div><button id="download-product" class="button primary">${icon('download',18)} Download extract</button><button id="download-selection" class="button">Download selection manifest</button><p class="small">Filtered from this completed analysis run. JSON embeds its manifest; use the second button to keep a companion manifest with a CSV export.</p></section>
 <div><section class="panel preview-table"><div class="panel-heading"><div><p class="eyebrow">PRODUCT PREVIEW</p><h2>Your first ${Math.min(8,rows.length)} rows</h2></div><span class="pill">Run ${data.run.id.slice(0,8)}</span></div><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(row=>`<tr>${headers.map(h=>`<td>${typeof row[h]==='number'?fmt(row[h],Number.isInteger(row[h])?0:4):esc(row[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="download-grid"><a class="download-card" href="./downloads/conservation-brief.html" target="_blank" rel="noopener">${icon('methods',26)}<strong>Conservation brief</strong><span>Findings, methods, limitations and citations. Print-ready HTML.</span><b>Open report ${icon('external',15)}</b></a><a class="download-card" href="./downloads/provenance.json" download>${icon('products',26)}<strong>Reproducibility manifest</strong><span>Input SHA-256 checksums, code fingerprints, configuration and versions.</span><b>Download JSON ${icon('download',15)}</b></a><a class="download-card" href="./downloads/model-evaluation.json" download>${icon('lab',26)}<strong>Experiment results</strong><span>Model metrics, calibration bins, fold sizes and paired comparison.</span><b>Download JSON ${icon('download',15)}</b></a><a class="download-card" href="./downloads/weekly-regions.csv" download>${icon('trends',26)}<strong>Complete annual cycle</strong><span>All 52 weeks for Michigan and each of the three analysis bands.</span><b>Download CSV ${icon('download',15)}</b></a><a class="download-card" href="./downloads/figures/annual-cycle.png" download>${icon('trends',26)}<strong>Annual-cycle figure</strong><span>Standalone scientific plot of all four regional summaries.</span><b>Download PNG ${icon('download',15)}</b></a><a class="download-card" href="./downloads/figures/regional-trends.png" download>${icon('trends',26)}<strong>Regional uncertainty figure</strong><span>Trend estimates and 80% ensemble intervals, ready to share.</span><b>Download PNG ${icon('download',15)}</b></a></div></div></div>`;
}

function methodsView(){
 const b=data.benchmark;
 return `${heading('05 / METHODS & LINEAGE','Methods & provenance','Trace the data, inspect the decisions, and understand the limits.',false)}
 <section class="architecture panel"><div class="panel-heading"><div><p class="eyebrow">REPRODUCIBLE BY DESIGN</p><h2>Scientific compute, separated from delivery.</h2></div><span class="pill">Run ${data.run.id}</span></div><div class="pipeline-flow">${[['01','Acquire','ebirdst · auk · WorldClim'],['02','Validate','Schemas · hashes · support'],['03','Analyze','terra / sf · Python · DuckDB'],['04','Package','CSV · GeoTIFF · GeoPackage'],['05','Communicate','Maps · experiments · brief']].map(([n,t,s])=>`<div><span>${n}</span><strong>${t}</strong><small>${s}</small></div>`).join('')}</div><p class="panel-note">The browser explores precomputed products. R and Python perform the scientific analysis locally; the hosted dashboard does not execute large jobs or access private observations.</p></section>
 <div class="two-col methods-cols"><section class="panel prose"><p class="eyebrow">SCIENTIFIC CONTRACT</p><h2>What these numbers mean</h2><details open><summary>Relative abundance is not population size.</summary><p>Cornell’s modeled relative abundance is an expected count for a standardized 2 km, 1 hour traveling checklist under optimized observation conditions. It is useful for comparing patterns within the product’s scope. It is not a census or an estimate of density in birds/km².</p></details><details open><summary>Seasonality and long-term trends are separate.</summary><p>The annual cycle uses the 2023 Status release. Breeding trends use the 2022 Trends release and cover 2012–2022. Their grids differ; the pipeline intersects each grid independently with the study region.</p></details><details><summary>Areas and missing support affect the denominator.</summary><p>Cell polygons intersect Michigan and custom latitude bands in EPSG:8857, an equal-area CRS. Weekly means use intersection area. Model zeros stay zero; missing cells are excluded, with supported area and support fraction included in every export. Coarse coastal cells imply a within-cell homogeneity assumption.</p></details><details><summary>Regional trend intervals preserve source replicates.</summary><p>For each of 100 ensemble replicates, the annual cell trends are weighted by abundance × clipped area. Regional estimates are summarized by median, 10th and 90th percentiles. We do not average cell interval endpoints or combine separate species ensembles.</p></details><details><summary>Environmental integration is real, but descriptive.</summary><p>WorldClim 2.1 SRTM-derived elevation at 10 arc minutes is cropped and averaged onto the 27 km Status grid. The dashboard exposes the covariate for inspection. We have not estimated a causal elevation effect or retrained Cornell’s model. The source is a static terrain covariate, not 2023 land cover.</p></details><details><summary>Two teaching datasets answer different questions.</summary><p>Michigan illustrates published model products. Singapore’s Collared Kingfisher observations illustrate effort filters, non-detection construction and spatial validation. They are never joined as if they described the same species, place, or year.</p></details></section>
 <div><section class="panel prose"><p class="eyebrow">MEASURED, NOT ASSUMED</p><h2>A small performance benchmark</h2><div class="benchmark-values"><div><strong>${fmt(b.pandas_median_ms,2)}<small> ms</small></strong><span>pandas · in memory</span></div><div><strong>${fmt(b.duckdb_median_ms,2)}<small> ms</small></strong><span>DuckDB · warm Parquet</span></div></div><p>${fmt(b.rows,0)} rows · ${b.repetitions} repetitions · equivalent numerical results. Parquet size: ${fmt(b.parquet_bytes/1024,1)} KiB.</p><p class="small">Different I/O paths; a teaching-scale measurement. This is not evidence of billion-record performance. The repository includes a SLURM template and a scaling plan, neither represented as an executed cluster run.</p></section><section class="panel prose source-list"><p class="eyebrow">DATA LINEAGE</p><h2>Primary sources</h2>${[['Cornell ebirdst','Official Status and Trends sample','https://ebird.github.io/ebirdst/'],['Status data · 2023','Fink et al. · released 2025','https://doi.org/10.2173/WZTW8903'],['Trends data · 2022','Fink et al. · released 2023','https://doi.org/10.2173/ebirdst.2022'],['Cornell auk','Singapore zero-filling teaching sample','https://github.com/CornellLabofOrnithology/auk/tree/main/inst/extdata'],['WorldClim 2.1','SRTM-derived elevation · 10 arc minutes','https://www.worldclim.org/data/worldclim21.html'],['Natural Earth','Public-domain context boundaries','https://www.naturalearthdata.com/about/terms-of-use/']].map(([n,d,u])=>`<a href="${u}" target="_blank" rel="noopener"><span><strong>${n}</strong><small>${d}</small></span>${icon('external',16)}</a>`).join('')}</section></div></div>
 <section class="science-callout"><span class="number-label">SCOPE</span><div><h3>Study scope & interpretation</h3><p>BirdScope analyzes the official Michigan Status and Trends sample and a separate Singapore checklist dataset. Results describe the supported regions and source releases. They support regional exploration; parcel-level decisions require finer data and independent ecological validation.</p></div><a href="./downloads/provenance.json" download class="button">${icon('download',17)} Run manifest</a></section>`;
}

function download(name,contents,type){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function notify(text){const t=$('#toast');t.textContent=text;t.hidden=false;setTimeout(()=>{if(t.isConnected)t.hidden=true;},3500);}
function stop(){state.play=false;clearInterval(timer);timer=null;}
function bind(){
 $('#region')?.addEventListener('change',e=>{state.region=e.target.value;state.selected=null;render();});
 $('#season')?.addEventListener('change',e=>{stop();state.season=e.target.value;if(state.season!=='all')state.week=series().find(r=>seasonFor(r.date,data.metadata.season_dates)===state.season).week;render();});
 $('#week')?.addEventListener('change',e=>{state.week=Number(e.target.value);state.season='all';const focus=e.target.id;render();$('#'+focus).focus();});
 document.querySelectorAll('[data-week]').forEach(e=>{const go=()=>{state.week=Number(e.dataset.week);render();};e.onclick=go;e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();go();}};});
 document.querySelectorAll('[data-layer]').forEach(e=>e.onclick=()=>{state.layer=e.dataset.layer;render();});
 document.querySelectorAll('[data-region]').forEach(e=>e.onclick=()=>{state.region=e.dataset.region;state.selected=null;render();window.scrollTo({top:0,behavior:'smooth'});});
 document.querySelectorAll('[data-cell]').forEach(e=>{const go=()=>{state.selected=e.dataset.cell;$('#cell-detail').innerHTML=cellDetails();document.querySelectorAll('.cell-selected').forEach(p=>p.classList.remove('cell-selected'));e.classList.add('cell-selected');};e.onclick=go;e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();go();}};});
 $('#play')?.addEventListener('click',()=>{if(state.play){stop();render();}else{state.play=true;state.season='all';render();timer=setInterval(()=>{state.week=state.week%52+1;render();},1000);}});
 [['product','product'],['product-region','productRegion'],['product-season','productSeason'],['format','format']].forEach(([id,key])=>$('#'+id)?.addEventListener('change',e=>{state[key]=e.target.value;render();}));
 $('#download-selection')?.addEventListener('click',()=>{const rows=selectProduct(data,state.productRegion,state.product,state.productSeason);download('birdscope-selection-manifest.json',JSON.stringify({run_id:data.run.id,region:state.productRegion,product:state.product,season:state.product==='trends'?'breeding':state.productSeason,rows:rows.length,source_versions:{status:2023,trends:2022},provenance_file:'provenance.json'},null,2),'application/json');});
 $('#download-product')?.addEventListener('click',()=>{const rows=selectProduct(data,state.productRegion,state.product,state.productSeason);const manifest={run_id:data.run.id,species:'yebsap-example',region:state.productRegion,product:state.product,season:state.product==='trends'?'breeding':state.productSeason,rows:rows.length,created_at:new Date().toISOString(),source_versions:{status:2023,trends:2022},interval:state.product==='trends'?'80% ensemble interval':'No regional interval inferred from cell intervals'};const name=`birdscope-${state.product}-${state.productRegion}`;if(state.format==='json')download(name+'.json',JSON.stringify({manifest,records:rows},null,2),'application/json');else{download(name+'.csv',csv(rows),'text/csv;charset=utf-8');}notify(`Downloaded ${rows.length} rows. ${state.format==='csv'?'Use the selection-manifest button for provenance.':'Provenance is embedded in the JSON.'}`);});
}
window.addEventListener('hashchange',()=>{stop();state.view=labels[location.hash.slice(1)]?location.hash.slice(1):'explorer';state.selected=null;render();window.scrollTo(0,0);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.play){stop();render();}});
boot();
